import itertools

def is_satisfiable(boolean_formula):
    """
    Determines whether a given Boolean formula is satisfiable.

    Parameters:
    boolean_formula (dict): Mapping of variable names to their possible truth values

    Returns:
    bool: True if the formula has at least one satisfying assignment, False otherwise
    """

    # Generate all possible truth assignments
    variables = boolean_formula.keys()
    assignments = list(itertools.product([True, False], repeat=len(variables)))

    # Evaluate the formula for each assignment
    for assignment in assignments:
        model = {var: val for var, val in zip(variables, assignment)}
        if evaluate_formula(boolean_formula, model):
            return True

    return False

def evaluate_formula(formula, model):
    """
    Helper function to evaluate a Boolean formula given a truth assignment.

    Parameters:
    formula (dict): Boolean formula as a nested logical structure
    model (dict): Current truth assignment

    Returns:
    bool: Whether the formula is true under the given model
    """
    # Recursive logic for nested Boolean operations
    if isinstance(formula, dict):
        if formula['op'] == 'AND':
            return all(evaluate_formula(child, model) for child in formula['args'])
        elif formula['op'] == 'OR':
            return any(evaluate_formula(child, model) for child in formula['args'])
        elif formula['op'] == 'NOT':
            return not evaluate_formula(formula['args'][0], model)
    elif formula in model:
        return model[formula]
    else:
        raise ValueError("Undefined variable in formula")

